\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates based on the description:
  % Parallelogram ABCD with B on the left, C at the top, D on the right, A at the bottom.
  % Let B = (0,0), C = (2, 3), D = (6, 3), A = (4, 0).
  % Check vectors: BC = (2, 3), AD = (6-4, 3-0) = (2,3). Parallelogram!

  \coordinate (B) at (0,0);
  \coordinate (C) at (2,3);
  \coordinate (D) at (6,3);
  \coordinate (A) at (4,0);

  % CD : CE = 1 : 2. Since CD = b = (4,0), length of CD is 4.
  % D is at (6,3), C is at (2,3), vector CD = (4,0).
  % CE must be 2 * CD = 8. So E is at (2 + 8, 3) = (10,3).
  \coordinate (E) at (10,3);

  % M is the midpoint of AD.
  % A = (4,0), D = (6,3) => M = (5, 1.5).
  \coordinate (M) at (5, 1.5);

  % N is on BC such that BN : BC = 1 : 4.
  % B = (0,0), C = (2,3). Vector BC = (2,3).
  % BN = 1/4 BC = (0.5, 0.75). So N = (0.5, 0.75).
  \coordinate (N) at (0.5, 0.75);

  % Draw parallelogram sides and extensions
  \draw (B) -- (C) -- (D) -- (A) -- cycle;
  \draw (D) -- (E);

  % Draw specified additional lines: ND and BM
  \draw (N) -- (D);
  \draw (B) -- (M);

  % Draw vectors with arrows in the middle and bold letters beside them
  % BN vector a: from B to N
  \draw[-{Stealth[length=5pt]}] (B) -- node[above left, inner sep=2pt] {$\mathbf{a}$} (N);
  % Note: BN has length 1/4 BC, let's make sure the arrow is clearly on BN.
  % Actually, BN is just the segment from B to N.

  % CD vector b: from C to D
  \draw[-{Stealth[length=5pt]}] (C) -- node[above, inner sep=2pt] {$\mathbf{b}$} (D);

  % Labels for vertices
  \node[left] at (B) {B};
  \node[above left] at (C) {C};
  \node[above right] at (D) {D};
  \node[right] at (E) {E};
  \node[below right] at (A) {A};
  \node[above] at (M) {M};
  \node[above left] at (N) {N};

  % Optional: draw small ticks for midpoints/ratios if desired, but not strictly requested.
  % Clean exam-style presentation.

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates based on the description:
  % Parallelogram ABCD with B on the left, C at the top, D on the right, A at the bottom.
  % Let B = (0,0), C = (2, 3), D = (6, 3), A = (4, 0).
  % CD length = 6 - 2 = 4.
  \coordinate (B) at (0,0);
  \coordinate (C) at (2,3);
  \coordinate (D) at (6,3);
  \coordinate (A) at (4,0);

  % CD : CE = 1 : 2. Since CD = 4, CE must be 8. 
  % Therefore DE = 4, making E at (10,3).
  % Wait, if CD : CE = 1 : 2, length of CE is 2 * length of CD.
  % Thus DE = CD. So E is at (6 + 4, 3) = (10,3) ... wait, 
  % Let's check coordinates: C=(2,3), D=(6,3) -> CD = 4.
  % If CE = 2 * CD = 8, then E = 2 + 8 = 10. E=(10,3).
  % Let's verify visual proportions: CD = 4 units, DE = 4 units => CE = 8 units. Perfect!
  \coordinate (E) at (10,3);

  % M is the midpoint of AD.
  % A = (4,0), D = (6,3) => M = (5, 1.5).
  \coordinate (M) at (5, 1.5);

  % N is on BC such that BN : BC = 1 : 4.
  % B = (0,0), C = (2,3). Vector BC = (2,3).
  % BN = 1/4 BC = (0.5, 0.75). So N = (0.5, 0.75).
  \coordinate (N) at (0.5, 0.75);

  % Draw parallelogram sides and extensions
  \draw (B) -- (C) -- (D) -- (A) -- cycle;
  \draw (D) -- (E);

  % Draw specified additional lines: ND and BM
  \draw (N) -- (D);
  \draw (B) -- (M);

  % Draw vectors with arrows in the middle and bold letters beside them
  % BN vector a: from B to N
  \draw[-{Stealth[length=5pt]}] (B) -- node[above left, inner sep=2pt] {$\mathbf{a}$} (N);

  % CD vector b: from C to D, with arrow and label b properly placed
  \draw[-{Stealth[length=5pt]}] (C) -- node[above, inner sep=2pt] {$\mathbf{b}$} (D);

  % Labels for vertices
  \node[left] at (B) {B};
  \node[above left] at (C) {C};
  \node[above right] at (D) {D};
  \node[right] at (E) {E};
  \node[below right] at (A) {A};
  \node[above] at (M) {M};
  \node[above left] at (N) {N};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates:
  % Parallelogram ABCD with B on the left, C at the top, D on the right, A at the bottom.
  \coordinate (B) at (0,0);
  \coordinate (C) at (2,3);
  \coordinate (D) at (6,3);
  \coordinate (A) at (4,0);

  % CD : CE = 1 : 2 means that C, D, E are collinear, D is between C and E,
  % and CD = DE, so E is at 2 * CD from C.
  % C = (2,3), D = (6,3) -> vector CD = (4,0).
  % Thus E = D + (4,0) = (10,3).
  \coordinate (E) at (10,3);

  % M is the midpoint of AD.
  % A = (4,0), D = (6,3) => M = (5, 1.5).
  \coordinate (M) at (5, 1.5);

  % N is on BC such that BN : BC = 1 : 4.
  % B = (0,0), C = (2,3). Vector BC = (2,3).
  % BN = 1/4 * BC = (0.5, 0.75). So N = (0.5, 0.75).
  \coordinate (N) at (0.5, 0.75);

  % Draw parallelogram sides and extension CD produced to E
  \draw (B) -- (C) -- (D) -- (A) -- cycle;
  \draw (D) -- (E);

  % Draw specified additional lines: ND and BM
  \draw (N) -- (D);
  \draw (B) -- (M);

  % Draw vector a along BN with arrow in the middle and bold letter beside it
  \draw[-{Stealth[length=5pt]}] (B) -- node[above left, inner sep=2pt] {$\mathbf{a}$} (N);

  % Draw vector b along CD with arrow in the middle and bold letter beside it
  \draw[-{Stealth[length=5pt]}] (C) -- node[above, inner sep=2pt] {$\mathbf{b}$} (D);

  % Labels for vertices
  \node[left] at (B) {B};
  \node[above left] at (C) {C};
  \node[above right] at (D) {D};
  \node[right] at (E) {E};
  \node[below right] at (A) {A};
  \node[above] at (M) {M};
  \node[above left] at (N) {N};

\end{tikzpicture}
